$ErrorActionPreference='Stop';$r='desktop/dist/win-unpacked/resources';$s=Join-Path $r 'sidecar/growthmap-sidecar.exe';@($s,(Join-Path $r 'frontend/index.html'),(Join-Path $r 'legal/LICENSE'),(Join-Path $r 'legal/EULA.md'),(Join-Path $r 'legal/PRIVACY.md'),(Join-Path $r 'legal/THIRD_PARTY_NOTICES.md'))|%{if(-not(Test-Path $_ -PathType Leaf)){throw "Missing packaged resource: $_"}};$port=Get-Random -Minimum 20000 -Maximum 50000;$token=[Convert]::ToBase64String([Security.Cryptography.RandomNumberGenerator]::GetBytes(32));$tmp=Join-Path $env:RUNNER_TEMP 'growthmap-sidecar-smoke';mkdir $tmp -Force|Out-Null;$env:GROWTHMAP_DESKTOP_MODE='1';$env:GROWTHMAP_SESSION_TOKEN=$token;$env:GROWTHMAP_PORT="$port";$env:DATABASE_URL="sqlite+aiosqlite:///$tmp/smoke.db";$env:GROWTHMAP_LICENSE_FILE="$tmp/license.json";$env:GROWTHMAP_STATIC_DIR=(Resolve-Path(Join-Path $r 'frontend'));$p=Start-Process $s -PassThru -WindowStyle Hidden;try{$ok=$false;1..100|%{if(-not$ok){try{$x=Invoke-WebRequest "http://127.0.0.1:$port/api/health/deep" -Headers @{Authorization="Bearer $token"} -UseBasicParsing;if($x.StatusCode-eq 200){$ok=$true}}catch{sleep -Milliseconds 150}}};if(-not$ok){throw 'Packaged sidecar authenticated health smoke failed'}}finally{Stop-Process $p -Force -ErrorAction SilentlyContinue};Write-Host 'Windows unpacked resource and authenticated sidecar smoke passed.'
